package net.fabricmc.fabric.api.event.player;

import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.EventFactory;
import net.minecraft.core.BlockPos;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

/** Fabric API: a player breaking a block (Omniloader stand-in; generated by tools/gen-fabric-events.py). */
public final class PlayerBlockBreakEvents {
    private PlayerBlockBreakEvents() {}

    public static final Event<Before> BEFORE = EventFactory.createArrayBacked(Before.class, ls -> (world, player, pos, state, blockEntity) -> { for (Before l : ls) if (!l.beforeBlockBreak(world, player, pos, state, blockEntity)) return false; return true; });
    public static final Event<After> AFTER = EventFactory.createArrayBacked(After.class, ls -> (world, player, pos, state, blockEntity) -> { for (After l : ls) l.afterBlockBreak(world, player, pos, state, blockEntity); });
    public static final Event<Canceled> CANCELED = EventFactory.createArrayBacked(Canceled.class, ls -> (world, player, pos, state, blockEntity) -> { for (Canceled l : ls) l.onBlockBreakCanceled(world, player, pos, state, blockEntity); });

    @FunctionalInterface public interface Before { boolean beforeBlockBreak(Level world, Player player, BlockPos pos, BlockState state, BlockEntity blockEntity); }
    @FunctionalInterface public interface After { void afterBlockBreak(Level world, Player player, BlockPos pos, BlockState state, BlockEntity blockEntity); }
    @FunctionalInterface public interface Canceled { void onBlockBreakCanceled(Level world, Player player, BlockPos pos, BlockState state, BlockEntity blockEntity); }
}
